INSERT INTO people_medication_intake(
    id, tenant_id, people_id, medication_id, intake_date, time_slot, dose_seq, status,
    taken_at, backfill, note, recorded_by_staff_id, is_deleted, gmt_created, gmt_modified, gmt_deleted
) VALUES (
    #{id}, #{tenantId}, #{peopleId}, #{medicationId}, #{intakeDate}, #{timeSlot},
    COALESCE(#{doseSeq}, 1), #{status},
    #{takenAt}, COALESCE(#{backfill}, 0), #{note}, #{recordedByStaffId}, #{isDeleted},
    #{gmtCreated}, #{gmtModified}, #{gmtDeleted}
)

